ALTER TABLE ai_center_content_page CHANGE COLUMN content_markdown content_html MEDIUMTEXT NOT NULL;
UPDATE ai_center_content_page SET content_html='<section><h2>如何使用</h2><ol><li>在 AI Center 选择一个 Runtime。</li><li>直接描述学习目标，也可以添加资料。</li><li>Workflow、Skill 和模型选择由平台在后台完成。</li><li>重要生成任务会在对话中请求确认框架与样式。</li></ol><blockquote>AI 可能会犯错，请核对课程事实、公式和重要结论。</blockquote></section>' WHERE page_key='USAGE_GUIDE';
UPDATE ai_center_content_page SET content_html='<section class="vcp-intro"><img src="https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&amp;fit=crop&amp;w=1600&amp;q=80" alt="VCP 概念视觉"><h2>从需求开始，而不是从答案开始</h2><p>VCP 将用于理解用户尚未完全表达清楚的需求，通过分阶段询问、方案探索和确认，形成可以执行的目标。</p><h3>计划能力</h3><ul><li>需求访谈与澄清</li><li>多轮方案比较</li><li>用户确认节点</li><li>将确认后的目标交给其他 Runtime</li></ul><p>当前页面用于介绍这一方向，执行能力将在后续需求明确后接入。</p></section>' WHERE page_key='VCP_INTRO';
